options.getOption:
// Taxis on the road, and a brush that filters the rest of the dashboard.
//
// Dragging across the curve writes the selected window, in seconds of the
// clock, to two dashboard variables (LO and HI); the map and the figures keep
// only the stretch of each trip inside it. The curve does not filter
// itself: it keeps showing the whole half hour the window was cut from.
// The query frame has columns `s` (seconds), `v0` and `v1` (cabs per vendor).
// @constants begin
const NOW = 't_now';
const LO = 't_lo';
const HI = 't_hi';
const STEP = 60;
const DOMAIN = [0, 2490];
const SERIES = [
  { field: 'v0', name: 'Vendor 0', color: '#ffb03b' },
  { field: 'v1', name: 'Vendor 1', color: '#38d6ff' },
];
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;

const frame = context.panel.data.series[0];
const column = (name) => (frame ? frame.fields.find((f) => f.name === name)?.values ?? [] : []);
const seconds = Array.from(column('s'), Number);

const clock = (s) => {
  const m = Math.floor(s / 60);
  return `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
};

// Whole minutes only, and never an empty window.
// The x axis is a category axis, one slot per ten-second sample: ECharts
// stacks two value axes along x, not y. Brush ranges come and go as slots.
const TICK = 10;
const slot = (s) => Math.max(0, Math.min(seconds.length - 1, Math.round(s / TICK)));
const snap = (slots) => {
  const lo = Math.max(DOMAIN[0], Math.floor((slots[0] * TICK) / STEP) * STEP);
  const hi = Math.min(DOMAIN[1], Math.max(Math.ceil((slots[1] * TICK) / STEP) * STEP, lo + STEP));
  return [lo, hi];
};
const drawBrush = (range) =>
  chart.dispatchAction({
    type: 'brush',
    areas: range ? [{ brushType: 'lineX', xAxisIndex: 0, coordRange: [slot(range[0]), slot(range[1])] }] : [],
  });
const publish = (range) => {
  location.partial({ ['var-' + LO]: range ? String(range[0]) : '', ['var-' + HI]: range ? String(range[1]) : '' }, true);
};

chart.off('brushEnd');
chart.off('brush');
chart.on('brushEnd', (event) => {
  const area = event.areas[0];
  if (!area || !area.coordRange) {
    publish(undefined);
    return;
  }
  const range = snap(area.coordRange);
  publish(range);
  setTimeout(() => drawBrush(range), 0);
});
chart.on('brush', (event) => {
  if (event.command === 'clear') {
    publish(undefined);
  }
});

// Every redraw wipes the brush: draw it back from the variables, which is
// also how a shared link arrives with its window.
const current = [
  parseFloat(context.grafana.replaceVariables('${' + LO + '}')),
  parseFloat(context.grafana.replaceVariables('${' + HI + '}')),
];
setTimeout(() => {
  chart.dispatchAction({ type: 'takeGlobalCursor', key: 'brush', brushOption: { brushType: 'lineX', brushMode: 'single' } });
  if (current.every(Number.isFinite)) {
    drawBrush(current);
  }
}, 0);

const muted = theme.colors.text.secondary;

// The bar at the instant the map is playing. The map writes its playhead to
// NOW several times a second; reading it from the URL and moving only the
// line keeps each step off the query path. `getOption` runs again on every
// render, so the previous listener is dropped before adding this one.
const EPOCH = 1767225600;
const nowSlot = () => {
  const raw = new URLSearchParams(location.getLocation().search).get('var-' + NOW);
  const ms = raw ? Date.parse(raw) : NaN;
  return Number.isFinite(ms) ? slot(ms / 1000 - EPOCH) : null;
};
const nowLine = (at) =>
  at === null
    ? { data: [] }
    : { symbol: 'none', silent: true, animation: false, label: { show: false }, lineStyle: { color: theme.colors.text.primary, width: 1.5, type: 'solid' }, data: [{ xAxis: at }] };
if (chart.__stopNow) {
  chart.__stopNow();
}
let drawnAt = nowSlot();
chart.__stopNow = location.getHistory().listen(() => {
  const at = nowSlot();
  if (at !== drawnAt) {
    drawnAt = at;
    chart.setOption({ series: [{ markLine: nowLine(at) }] }, { lazyUpdate: true });
  }
});

return {
  animation: false,
  grid: { left: 8, right: 16, top: 30, bottom: 44, containLabel: true },
  legend: { bottom: 0, left: 0, icon: 'rect', itemWidth: 14, itemHeight: 3, textStyle: { color: muted } },
  tooltip: {
    trigger: 'axis',
    formatter: (items) => {
      const rows = items.map((it) => `${it.marker}${it.seriesName}: <b>${it.value}</b>`).join('<br/>');
      return `${clock(Number(items[0].axisValue))}<br/>${rows}`;
    },
  },
  toolbox: {
    right: 8,
    top: 0,
    itemSize: 14,
    feature: { brush: { type: ['lineX', 'clear'], title: { lineX: 'Select a window', clear: 'Clear the filter' } } },
  },
  brush: {
    xAxisIndex: 0,
    brushType: 'lineX',
    brushMode: 'single',
    transformable: true,
    brushStyle: { color: 'rgba(128, 128, 128, 0.14)', borderColor: muted, borderWidth: 1 },
  },
  xAxis: {
    type: 'category',
    data: seconds,
    boundaryGap: false,
    axisTick: { show: false },
    axisLabel: { color: muted, interval: (i, s) => Number(s) % 300 === 0, formatter: (s) => clock(Number(s)) },
  },
  yAxis: { type: 'value', name: 'taxis', nameTextStyle: { color: muted }, axisLabel: { color: muted }, splitLine: { lineStyle: { opacity: 0.15 } } },
  series: SERIES.map((s, i) => {
    const values = Array.from(column(s.field), Number);
    return {
      name: s.name,
      type: 'line',
      stack: 'taxis',
      smooth: true,
      showSymbol: false,
      lineStyle: { width: 2, color: s.color },
      itemStyle: { color: s.color },
      areaStyle: {
        color: {
          type: 'linear', x: 0, y: 0, x2: 0, y2: 1,
          colorStops: [{ offset: 0, color: s.color + '55' }, { offset: 1, color: s.color + '05' }],
        },
      },
      data: values,
      ...(i === 0 ? { markLine: nowLine(drawnAt) } : {}),
    };
  }),
};
